	array(
		'question_text' => 'Which of the following should generally be included in informed consent?',
		'option_a' => 'Nature of treatment, risks, benefits, alternatives, fees, and limits of confidentiality',
		'option_b' => 'Personal opinions about previous clients',
		'option_c' => 'A complete list of all treatment techniques the therapist knows',
		'option_d' => 'Future diagnoses that may develop',
