	array(
		'question_text' => 'Which statement best reflects the CTA Crisis Framework taught in this course?',
		'option_a' => 'Act quickly before additional information is gathered',
		'option_b' => 'Pause, assess, clarify, consult, protect, and document',
		'option_c' => 'Warn first and assess later',
		'option_d' => 'Refer all crisis situations to emergency services',
